<script setup>
import { computed, ref } from 'vue'
const props = defineProps({ party: Object })
const emit = defineEmits(['navigate'])
const data = props.party || {}
const date = value => value ? new Intl.DateTimeFormat('ru-RU', { day:'numeric', month:'long', year:'numeric' }).format(new Date(value)) : 'Нет данных'
const value = input => input || 'Нет данных'
const active = ref('summary')
const tabs = [['summary','Сводка'],['risks','Риски'],['courts','Суды'],['links','Связи'],['finance','Финансы'],['purchases','Закупки'],['guarant','Гарант']]
const unavailable = computed(() => ({ courts:['Суды','Картотека арбитражных дел'], links:['Связи','ЕГРЮЛ / граф связей'], finance:['Финансы','Росстат / бухгалтерская отчётность'], purchases:['Закупки','ЕИС госзакупок'] })[active.value])
function downloadReport() { const blob = new Blob([JSON.stringify(data, null, 2)], { type:'application/json' }); const url=URL.createObjectURL(blob); const link=document.createElement('a'); link.href=url; link.download=`smart-retail-${data.inn||'report'}.json`; link.click(); URL.revokeObjectURL(url) }
</script>
<template><section class="border-b border-[#242424] px-[50px] pb-0 pt-8"><div class="flex justify-between"><div><p class="text-sm text-[#777]">{{data.inn}}</p><h1 class="mt-2 text-[37px] font-medium">{{data.name}}</h1><p class="mt-2 text-[16px] text-[#999]"><span class="text-[#8ad5af]">● {{data.status==='ACTIVE'?'Действует':value(data.status)}}</span>&nbsp;&nbsp; {{value(data.city)}}&nbsp;&nbsp; с {{date(data.registration_date)}}&nbsp;&nbsp; {{value(data.okved)}}</p><p class="mt-4 text-sm text-[#6f6f74]">Источник: DaData / ЕГРЮЛ · проверено сейчас</p></div><div class="flex h-fit gap-3"><button class="rounded-full border border-[#343438] px-4 py-2" @click="downloadReport">Скачать JSON</button><button class="rounded-full bg-white px-5 py-2 text-black" @click="emit('navigate','escrow')">Открыть гарант</button></div></div><nav class="mt-6 flex gap-8 text-sm text-[#89898e]"><button v-for="[key,label] in tabs" :key="key" class="pb-4" :class="active===key?'border-b-2 border-white text-white':''" @click="key==='guarant'?emit('navigate','escrow'):active=key">{{label}}</button></nav></section><div class="grid grid-cols-[334px_1fr] gap-7 px-[50px] py-8"><aside class="h-fit rounded-2xl border border-[#292929] bg-[#121212] p-5"><p class="text-sm text-[#85858a]">Руководитель</p><p class="mt-3 text-[18px]">{{value(data.director)}}</p><p class="mt-3 text-[#8f8f93]">{{value(data.manager_position)}}</p><div class="mt-4 grid grid-cols-2 gap-y-4 text-sm"><span class="text-[#777]">ОГРН<br><b class="text-white">{{value(data.ogrn)}}</b></span><span class="text-[#777]">ИНН<br><b class="text-white">{{value(data.inn)}}</b></span><span class="text-[#777]">КПП<br><b class="text-white">{{value(data.kpp)}}</b></span><span class="text-[#777]">Регистрация<br><b class="text-white">{{date(data.registration_date)}}</b></span></div><p class="mt-5 text-sm text-[#777]">Адрес</p><p class="mt-2">{{value(data.address)}}</p><button class="mt-6 w-full rounded-xl border border-[#303030] p-3 text-left" @click="downloadReport">Сводный отчёт<br><small class="text-[#777]">скачать актуальные реквизиты</small></button></aside><main><template v-if="active==='summary'"><section class="grid grid-cols-3 overflow-hidden rounded-2xl border border-[#292929]"><div v-for="item in [['Риск',value(data.risk_level),data.risk_factors?.join(', ')],['Статус',value(data.status),'сведения ЕГРЮЛ'],['ОКВЭД',value(data.okved),'основной вид деятельности'],['Арбитраж','Нет данных','нужен отдельный источник'],['ФССП','Нет данных','нужен отдельный источник'],['Санкции','Нет данных','нужен отдельный источник']]" class="border-b border-r border-[#292929] p-5"><p class="text-[#85858a]">{{item[0]}}</p><strong class="mt-1 block text-[20px]">{{item[1]}}</strong><small class="text-[#777]">{{item[2]}}</small></div></section><h2 class="mt-7 font-medium">Реквизиты</h2><dl class="mt-2 text-[16px]"><div v-for="item in [['ОГРН',value(data.ogrn)],['ИНН / КПП',value(data.inn)+'     /     '+value(data.kpp)],['Форма',value(data.legal_form)],['Дата регистрации',date(data.registration_date)],['ОКВЭД',value(data.okved)],['Адрес',value(data.address)],['Уставный капитал',data.authorized_capital ? Number(data.authorized_capital).toLocaleString('ru-RU')+' ₽' : 'Нет данных']]" class="grid grid-cols-[145px_1fr] border-b border-[#262626] py-3"><dt class="text-[#777]">{{item[0]}}</dt><dd>{{item[1]}}</dd></div></dl></template><section v-else-if="active==='risks'" class="rounded-2xl border border-[#292929] bg-[#121212] p-7"><p class="text-sm text-[#85858a]">Автоматическая оценка по данным карточки организации</p><h2 class="mt-3 text-3xl">Риск: {{value(data.risk_level)}}</h2><ul class="mt-6 space-y-4"><li v-for="factor in data.risk_factors" class="flex gap-3"><span class="mt-2 h-2 w-2 rounded-full bg-[#d4ff34]"></span>{{factor}}</li></ul></section><section v-else class="rounded-2xl border border-[#292929] bg-[#121212] p-7"><p class="text-sm text-[#85858a]">{{unavailable?.[1]}}</p><h2 class="mt-3 text-3xl">{{unavailable?.[0]}}</h2><p class="mt-5 max-w-xl leading-7 text-[#999]">Раздел переключается и готов к отображению данных, но подключённый DaData API не предоставляет эти сведения. Для наполнения нужен отдельный официальный источник.</p><button class="mt-7 rounded-full border border-[#444] px-5 py-3" @click="active='summary'">Вернуться к сводке</button></section></main></div></template>
